  <script>
    // Normalise typed Eastern Arabic or Persian digits to Western digits
    function toWesternDigits(value) {
      if (!value) return '';
      return value
        .replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 1632))
        .replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 1776));
    }

    const inputs = Array.from(document.querySelectorAll('.otp-field'));
    const verifyBtn = document.getElementById('btn-submit');
    const timerContainer = document.getElementById('timer-container');
    const countdownEl = document.getElementById('countdown');
    const resendBtn = document.getElementById('btn-resend');
    const toast = document.getElementById('toast');
    const btnSpinner = document.getElementById('btn-spinner');
    const btnText = document.getElementById('btn-text');

    let timeLeft = 45;
    let timerId = null;

    // Check if code is fully entered to enable Verify button
    function updateVerifyState() {
      const code = inputs.map(input => input.value).join('');
      verifyBtn.disabled = code.length !== 6;
      inputs.forEach(input => {
        input.classList.toggle('filled', input.value.length > 0);
      });
    }

    // Input interaction & paste handlers
    inputs.forEach((input, index) => {
      input.addEventListener('input', (e) => {
        let val = toWesternDigits(e.target.value);
        val = val.replace(/\D/g, '');

        if (val.length > 1) {
          // If multi-digit typed or pasted in single box
          fillFromIndex(index, val);
          return;
        }

        input.value = val;
        if (val && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        updateVerifyState();
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace') {
          if (!input.value && index > 0) {
            inputs[index - 1].focus();
            inputs[index - 1].value = '';
          } else {
            input.value = '';
          }
          updateVerifyState();
        } else if (e.key === 'ArrowLeft') {
          // In LTR inputs container: left arrow moves to previous digit
          if (index > 0) inputs[index - 1].focus();
        } else if (e.key === 'ArrowRight') {
          if (index < inputs.length - 1) inputs[index + 1].focus();
        }
      });

      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const pasted = (e.clipboardData || window.clipboardData).getData('text');
        const digits = toWesternDigits(pasted).replace(/\D/g, '');
        if (digits) {
          fillFromIndex(0, digits);
        }
      });
    });

    function fillFromIndex(startIndex, str) {
      const chars = str.split('');
      let charIndex = 0;
      for (let i = startIndex; i < inputs.length && charIndex < chars.length; i++) {
        inputs[i].value = chars[charIndex];
        charIndex++;
      }
      const nextFocus = Math.min(startIndex + chars.length, inputs.length - 1);
      inputs[nextFocus].focus();
      updateVerifyState();
    }

    // Countdown logic
    function startTimer() {
      timeLeft = 45;
      timerContainer.style.display = 'inline-flex';
      resendBtn.style.display = 'none';
      countdownEl.textContent = `0:${timeLeft < 10 ? '0' : ''}${timeLeft}`;

      if (timerId) clearInterval(timerId);

      timerId = setInterval(() => {
        timeLeft--;
        if (timeLeft <= 0) {
          clearInterval(timerId);
          timerContainer.style.display = 'none';
          resendBtn.style.display = 'inline-block';
        } else {
          countdownEl.textContent = `0:${timeLeft < 10 ? '0' : ''}${timeLeft}`;
        }
      }, 1000);
    }

    function showToast(message) {
      document.getElementById('toast-message').textContent = message;
      toast.classList.add('show');
      setTimeout(() => {
        toast.classList.remove('show');
      }, 3500);
    }

    function handleResendCode() {
      inputs.forEach(input => {
        input.value = '';
        input.classList.remove('filled', 'error');
      });
      inputs[0].focus();
      updateVerifyState();
      startTimer();
      showToast('تم إرسال رمز تحقق جديد إلى هاتفك');
    }

    function handleVerify() {
      btnSpinner.style.display = 'inline-block';
      btnText.textContent = 'جارٍ التحقق...';
      verifyBtn.disabled = true;

      // Simulate network verification
      setTimeout(() => {
        btnSpinner.style.display = 'none';
        btnText.textContent = 'تأكيد';
        verifyBtn.disabled = false;
        showToast('تم التحقق بنجاح');
      }, 1200);
    }

    // Initialize
    window.addEventListener('DOMContentLoaded', () => {
      startTimer();
      inputs[0].focus();
    });
  </script>
